from __future__ import annotations

from wolframtas_orchestrator.movement_model import (
    _table,
    derive_movement_arrays,
    derive_movement_model,
    retention_for,
)

# Regression anchors: the shared movement_constants.json (generated by
# tools/gen_movement_constants.py in numpy float32) must keep these exact values,
# which the C++ exact solver reads bit-for-bit from its generated twin.
KNOWN_RETENTION = {
    "flat_ground": 0.546000063419342,
    "air": 0.9100000262260437,
    "slime": 0.7280000448226929,
    "ice": 0.891800045967102,
    "water": 0.800000011920929,
    "lava": 0.5000000596046448,
    "none": 0.0,
}


def test_table_retention_matches_known_reference_values() -> None:
    for medium, value in KNOWN_RETENTION.items():
        assert retention_for(medium) == value


def _movement_slot(**controls):
    base = {"forward": 1, "strafe": 0, "jump": False, "sneak": False, "sprint": False}
    base.update(controls)
    return base


def test_derive_flat_sprintjump_arrays_from_movement_plan() -> None:
    table = _table()
    plan = {
        "version": 1,
        "slot_indexing": "1_based",
        "slots": [
            {"slot": 1, "kind": "init", "speed": 0.0, "imux": KNOWN_RETENTION["air"], "imuz": KNOWN_RETENTION["air"]},
            {
                "slot": 2,
                "kind": "movement",
                "controls": _movement_slot(jump=True, sprint=True),
                "acceleration": {"medium": "ground"},
                "retention": {"medium": "flat_ground"},
            },
            {
                "slot": 3,
                "kind": "movement",
                "controls": _movement_slot(sprint=True),
                "acceleration": {"medium": "air"},
                "retention": {"medium": "air"},
            },
        ],
    }

    arrays = derive_movement_arrays(plan)

    assert arrays["imux"] == [KNOWN_RETENTION["air"], KNOWN_RETENTION["flat_ground"], KNOWN_RETENTION["air"]]
    assert arrays["imuz"] == arrays["imux"]
    # Ground sprint-jump: base * no45 factor + sprint-jump boost.
    expect_sprintjump = (
        table["base_movement"]["ground_flat_ground_sprint"] * table["input_factor"]["no45"]
        + table["sprintjump_boost"]
    )
    # Air slot, sprint delayed one tick: prev slot (the sprint-jump) was sprinting,
    # so this air tick uses the air_sprint base.
    expect_air = table["base_movement"]["air_sprint"] * table["input_factor"]["no45"]
    assert arrays["mmu"] == [0.0, expect_sprintjump, expect_air]


def test_air_sprint_is_delayed_one_tick() -> None:
    table = _table()
    plan = {
        "version": 1,
        "slot_indexing": "1_based",
        "slots": [
            # First air slot sprinting, but no prior sprint -> air_walk base.
            {
                "slot": 1,
                "kind": "movement",
                "controls": _movement_slot(sprint=True),
                "acceleration": {"medium": "air"},
                "retention": {"medium": "air"},
            },
            # Now the prior tick was sprinting -> air_sprint base.
            {
                "slot": 2,
                "kind": "movement",
                "controls": _movement_slot(sprint=True),
                "acceleration": {"medium": "air"},
                "retention": {"medium": "air"},
            },
        ],
    }

    arrays = derive_movement_arrays(plan)

    assert arrays["mmu"] == [
        table["base_movement"]["air_walk"] * table["input_factor"]["no45"],
        table["base_movement"]["air_sprint"] * table["input_factor"]["no45"],
    ]


def test_web_approximation_edits_imu_and_mmu() -> None:
    table = _table()
    air = KNOWN_RETENTION["air"]
    plan = {
        "version": 1,
        "slot_indexing": "1_based",
        "slots": [
            # Normal air tick feeding the web tick: its retention is quartered
            # (it scales the momentum carried into the web).
            {
                "slot": 1,
                "kind": "movement",
                "controls": _movement_slot(),
                "acceleration": {"medium": "air"},
                "retention": {"medium": "air"},
            },
            # Web tick: mmu quartered, retention zeroed (carry dropped after it).
            {
                "slot": 2,
                "kind": "movement",
                "controls": _movement_slot(),
                "acceleration": {"medium": "air"},
                "retention": {"medium": "air"},
                "web": True,
            },
        ],
    }

    arrays = derive_movement_arrays(plan)

    factor = table["web_motion_factor"]
    base_air_walk = table["base_movement"]["air_walk"] * table["input_factor"]["no45"]
    assert arrays["imux"] == [air * factor, 0.0]
    assert arrays["imuz"] == [air * factor, 0.0]
    assert arrays["mmu"] == [base_air_walk, base_air_walk * factor]


def test_derive_init_slot_as_first_mmu_entry() -> None:
    plan = {
        "version": 1,
        "slot_indexing": "1_based",
        "slots": [
            {"slot": 1, "kind": "init", "speed": 0.25, "imux": KNOWN_RETENTION["air"], "imuz": KNOWN_RETENTION["flat_ground"]}
        ],
    }

    model = derive_movement_model(plan)

    assert model["arrays"] == {
        "imux": [KNOWN_RETENTION["air"]],
        "imuz": [KNOWN_RETENTION["flat_ground"]],
        "mmu": [0.25],
    }


def test_derive_fluid_and_wall_hit_from_movement_plan() -> None:
    table = _table()
    plan = {
        "version": 1,
        "slot_indexing": "1_based",
        "slots": [
            {
                "slot": 1,
                "kind": "movement",
                "controls": _movement_slot(sprint=True),
                "acceleration": {"medium": "water", "input": "no45_forward"},
                "retention": {"medium": "water"},
                "wall_hit": {"axes": ["x"]},
            },
            {
                "slot": 2,
                "kind": "movement",
                "controls": _movement_slot(strafe=1, sprint=True),
                "acceleration": {"medium": "lava", "input": "forward_45"},
                "retention": {"medium": "lava"},
            },
        ],
    }

    arrays = derive_movement_arrays(plan)

    assert arrays["imux"] == [0.0, KNOWN_RETENTION["lava"]]
    assert arrays["imuz"] == [KNOWN_RETENTION["water"], KNOWN_RETENTION["lava"]]
    assert arrays["mmu"] == [
        table["base_movement"]["water"] * table["input_factor"]["no45"],
        table["base_movement"]["lava"] * table["input_factor"]["forward_45"],
    ]
